/**
 * drm_abi_hosttest.c: the user ABI of rach2/sys/drm/uapi.h against Linux
 * 6.12's: the size and alignment of every structure and union, the offset
 * and size of every member, and every ioctl number, on x86-64 and on i386.
 *
 * The rows hold Linux's numbers for both ABIs. They were read from Linux
 * 6.12's own headers (include/uapi/drm/drm.h, drm_mode.h, drm_fourcc.h,
 * include/uapi/linux/dma-buf.h, sync_file.h, udmabuf.h, and the sw_sync
 * structures of drivers/dma-buf/sw_sync.c), compiled by clang for
 * i386-linux-gnu and x86_64-linux-gnu, for each aggregate and member that
 * uapi.h declares, with offsetof, sizeof and _Alignof. To read them again
 * after uapi.h gains a structure, compile those expressions over Linux's
 * headers in the same way and add the rows.
 *
 * The host compiles uapi.h for its own ABI only, which is checked against
 * the column of its pointer width. The i386 column is checked by laying out
 * each aggregate again by that ABI's rules from the class of each member's
 * type as uapi.h declares it: a pointer, `intptr_t`, `uintptr_t` or
 * `size_t` is 4 bytes, aligned to 4; a 64-bit integer is 8 bytes, aligned to
 * 4; any other scalar keeps its size as its alignment; an array, a nested
 * aggregate and an anonymous structure follow from their elements. So a
 * 64-bit integer where Linux has a `long` fails here although x86-64 agrees.
 * An ioctl's i386 number is its host number with the i386 size of its
 * argument.
 */
#include "drm/uapi.h"

extern int printf(const char *format, ...);
extern int strcmp(const char *a, const char *b);

enum { R_AGG, R_MEM, R_FIELD, R_IOCTL };

/* The class of a scalar's type, which fixes its i386 size and alignment. */
enum { C_PLAIN, C_WORD, C_QUAD, C_AGG, C_ANON };

#define IS_UNION_struct 0
#define IS_UNION_union  1

#define CLASS(e)                                                       \
    (__builtin_classify_type(e) == 5 ? C_WORD                          \
     : __builtin_types_compatible_p(__typeof__(e), intptr_t) ||        \
             __builtin_types_compatible_p(__typeof__(e), uintptr_t) || \
             __builtin_types_compatible_p(__typeof__(e), size_t)       \
         ? C_WORD                                                      \
     : __builtin_types_compatible_p(__typeof__(e), uint64_t) ||        \
             __builtin_types_compatible_p(__typeof__(e), int64_t)      \
         ? C_QUAD                                                      \
         : C_PLAIN)

/*
 * A row: an aggregate, a member, a field of an anonymous structure or an
 * ioctl number. `nat` is what the host compiler gives: an aggregate's size
 * and alignment, a member's or field's offset and size, an ioctl's number.
 * A member's elements are `count` of class `cls` and native size `elem`;
 * `sub` names a nested aggregate or an ioctl's argument. `l32` and `l64` are
 * Linux's numbers on i386 and x86-64, in the same order as `nat`.
 */
struct row {
    int what;
    int is_union;
    const char *agg;
    const char *name;
    const char *sub;
    unsigned long nat[2];
    unsigned long count;
    int cls;
    unsigned long elem;
    unsigned long l32[2], l64[2];
};

#define M_(k, t, m)    (((k t *)0)->m)
#define COUNT(k, t, m) (sizeof(M_(k, t, m)) / sizeof(M_(k, t, m)[0]))

#define AGG(k, t, s32, a32, s64, a64)                                                 \
    {R_AGG, IS_UNION_##k, #t, #t,         0,         {sizeof(k t), __alignof__(k t)}, \
     0,     C_AGG,        0,  {s32, a32}, {s64, a64}},
#define MEM_S(k, t, m, o32, s32, o64, s64)    \
    {R_MEM,                                   \
     0,                                       \
     #t,                                      \
     #m,                                      \
     0,                                       \
     {offsetof(k t, m), sizeof(M_(k, t, m))}, \
     1,                                       \
     CLASS(M_(k, t, m)),                      \
     sizeof(M_(k, t, m)),                     \
     {o32, s32},                              \
     {o64, s64}},
#define MEM_A(k, t, m, o32, s32, o64, s64)    \
    {R_MEM,                                   \
     0,                                       \
     #t,                                      \
     #m,                                      \
     0,                                       \
     {offsetof(k t, m), sizeof(M_(k, t, m))}, \
     COUNT(k, t, m),                          \
     CLASS(M_(k, t, m)[0]),                   \
     sizeof(M_(k, t, m)[0]),                  \
     {o32, s32},                              \
     {o64, s64}},
#define MEM_N(k, t, m, sub, o32, s32, o64, s64)                      \
    {R_MEM,      0,         #t,                                      \
     #m,         #sub,      {offsetof(k t, m), sizeof(M_(k, t, m))}, \
     1,          C_AGG,     sizeof(M_(k, t, m)),                     \
     {o32, s32}, {o64, s64}},
#define MEM_NA(k, t, m, sub, o32, s32, o64, s64) \
    {R_MEM,                                      \
     0,                                          \
     #t,                                         \
     #m,                                         \
     #sub,                                       \
     {offsetof(k t, m), sizeof(M_(k, t, m))},    \
     COUNT(k, t, m),                             \
     C_AGG,                                      \
     sizeof(M_(k, t, m)[0]),                     \
     {o32, s32},                                 \
     {o64, s64}},
#define MEM_X(k, t, m, o32, s32, o64, s64)                           \
    {R_MEM,      0,         #t,                                      \
     #m,         0,         {offsetof(k t, m), sizeof(M_(k, t, m))}, \
     1,          C_ANON,    sizeof(M_(k, t, m)),                     \
     {o32, s32}, {o64, s64}},
#define MEM_XA(k, t, m, o32, s32, o64, s64)   \
    {R_MEM,                                   \
     0,                                       \
     #t,                                      \
     #m,                                      \
     0,                                       \
     {offsetof(k t, m), sizeof(M_(k, t, m))}, \
     COUNT(k, t, m),                          \
     C_ANON,                                  \
     sizeof(M_(k, t, m)[0]),                  \
     {o32, s32},                              \
     {o64, s64}},
#define FIELD_S(k, t, path, f)                                                \
    {R_FIELD,                                                                 \
     0,                                                                       \
     #t,                                                                      \
     #path "." #f,                                                            \
     0,                                                                       \
     {offsetof(k t, path.f) - offsetof(k t, path), sizeof(M_(k, t, path.f))}, \
     1,                                                                       \
     CLASS(M_(k, t, path.f)),                                                 \
     sizeof(M_(k, t, path.f)),                                                \
     {0, 0},                                                                  \
     {0, 0}},
#define FIELD_A(k, t, path, f)                                                \
    {R_FIELD,                                                                 \
     0,                                                                       \
     #t,                                                                      \
     #path "." #f,                                                            \
     0,                                                                       \
     {offsetof(k t, path.f) - offsetof(k t, path), sizeof(M_(k, t, path.f))}, \
     COUNT(k, t, path.f),                                                     \
     CLASS(M_(k, t, path.f)[0]),                                              \
     sizeof(M_(k, t, path.f)[0]),                                             \
     {0, 0},                                                                  \
     {0, 0}},
#define IOCTL_N(n, n32, n64) {R_IOCTL, 0, "", #n, 0, {n, 0}, 0, C_PLAIN, 0, {n32, 0}, {n64, 0}},
#define IOCTL_A(n, agg, n32, n64) \
    {R_IOCTL, 0, "", #n, #agg, {n, 0}, 1, C_AGG, 0, {n32, 0}, {n64, 0}},
#define IOCTL_S(n, type, n32, n64) \
    {R_IOCTL, 0, "", #n, 0, {n, 0}, 1, CLASS((type)0), sizeof(type), {n32, 0}, {n64, 0}},

