#define NROWS ((int)(sizeof(rows) / sizeof(rows[0])))

static int failures;

/** Record a mismatch of `what` in row `r`: the value found and Linux's,
 * in hexadecimal, which suits an ioctl number and reads well enough for a
 * size. */
static void mismatch(const struct row *r, const char *what, unsigned long got, unsigned long want)
{
    printf("drm-abi-hosttest: fail: %s%s%s %s: %#lx, Linux has %#lx\n", r->agg, *r->agg ? " " : "",
           r->name, what, got, want);
    failures++;
}

/** The i386 size and alignment of a scalar of class `cls` whose host size
 * is `n`. */
static void scalar32(int cls, unsigned long n, unsigned long *size, unsigned long *align)
{
    *size = cls == C_WORD ? 4 : n;
    *align = cls == C_WORD || cls == C_QUAD ? 4 : n;
}

static void layout32(int a, int report, unsigned long *size, unsigned long *align);

/** The index of the aggregate row named `name`, or -1. */
static int agg_row(const char *name)
{
    int i;

    for (i = 0; i < NROWS; i++) {
        if (rows[i].what == R_AGG && strcmp(rows[i].name, name) == 0) {
            return i;
        }
    }
    return -1;
}

/** The i386 size and alignment of one element of the member at row `m`:
 * a scalar by its class, a nested aggregate by its own layout, and an
 * anonymous structure by the field rows after it. */
static void element32(int m, unsigned long *size, unsigned long *align)
{
    const struct row *r = &rows[m];
    unsigned long end = 0, fs, fa;
    int a, i;

    if (r->cls == C_AGG) {
        a = agg_row(r->sub);
        if (a < 0) {
            mismatch(r, "nested aggregate without a row", 0, 0);
            *size = *align = 1;
            return;
        }
        layout32(a, 0, size, align);
        return;
    }
    if (r->cls != C_ANON) {
        scalar32(r->cls, r->elem, size, align);
        return;
    }
    *align = 1;
    for (i = m + 1; i < NROWS && rows[i].what == R_FIELD; i++) {
        scalar32(rows[i].cls, rows[i].elem, &fs, &fa);
        end = (end + fa - 1) / fa * fa + fs * rows[i].count;
        *align = fa > *align ? fa : *align;
    }
    *size = (end + *align - 1) / *align * *align;
}

/**
 * Lay out the aggregate at row `a` by i386's rules: each member at the
 * next multiple of its alignment, a union's all at 0, the whole rounded to
 * its largest alignment. With `report`, each member's offset and size and
 * the whole's size and alignment are compared with Linux's i386 numbers.
 */
static void layout32(int a, int report, unsigned long *size, unsigned long *align)
{
    unsigned long end = 0, off, es, ea, msize;
    int i;

    *align = 1;
    for (i = a + 1; i < NROWS && rows[i].what != R_AGG && rows[i].what != R_IOCTL; i++) {
        if (rows[i].what != R_MEM) {
            continue;
        }
        element32(i, &es, &ea);
        msize = es * rows[i].count;
        off = rows[a].is_union ? 0 : (end + ea - 1) / ea * ea;
        if (report && off != rows[i].l32[0]) {
            mismatch(&rows[i], "i386 offset", off, rows[i].l32[0]);
        }
        if (report && msize != rows[i].l32[1]) {
            mismatch(&rows[i], "i386 size", msize, rows[i].l32[1]);
        }
        end = off + msize > end ? off + msize : end;
        *align = ea > *align ? ea : *align;
    }
    *size = (end + *align - 1) / *align * *align;
    if (report && *size != rows[a].l32[0]) {
        mismatch(&rows[a], "i386 size", *size, rows[a].l32[0]);
    }
    if (report && *align != rows[a].l32[1]) {
        mismatch(&rows[a], "i386 alignment", *align, rows[a].l32[1]);
    }
}

/** Compare the host's numbers of row `r` with Linux's column for the host's
 * pointer width. */
static void check_native(const struct row *r)
{
    const unsigned long *want = sizeof(void *) == 8 ? r->l64 : r->l32;

    if (r->what == R_FIELD) {
        return;
    }
    if (r->nat[0] != want[0]) {
        mismatch(r,
                 r->what == R_AGG   ? "size"
                 : r->what == R_MEM ? "offset"
                                    : "number",
                 r->nat[0], want[0]);
    }
    /* Linux's udmabuf_create_list ends in a flexible array of items,
       which C89 cannot declare; its size is Linux's, and its alignment,
       which nothing that holds it reads, is that of its 32-bit members. */
    if (r->what == R_AGG && strcmp(r->name, "udmabuf_create_list") == 0) {
        return;
    }
    if (r->what != R_IOCTL && r->nat[1] != want[1]) {
        mismatch(r, r->what == R_AGG ? "alignment" : "size", r->nat[1], want[1]);
    }
}

/** Check the i386 number of the ioctl at row `r`: its host number with
 * the i386 size of its argument, and that the decoding macros take it
 * apart as Linux's encoding put it together. */
static void check_ioctl32(const struct row *r)
{
    unsigned long size = 0, align;
    unsigned long n;

    if (r->cls == C_AGG) {
        int a = agg_row(r->sub);

        if (a < 0) {
            mismatch(r, "argument without a row", 0, 0);
            return;
        }
        layout32(a, 0, &size, &align);
    } else if (r->count) {
        scalar32(r->cls, r->elem, &size, &align);
    }
    n = r->count ? (r->nat[0] & ~(0x3FFFul << 16)) | (size << 16) : r->nat[0];
    if (n != r->l32[0]) {
        mismatch(r, "i386 number", n, r->l32[0]);
    }
    if (UAPI_IOC_DIR(r->l32[0]) != UAPI_IOC_DIR(r->nat[0]) ||
        UAPI_IOC_TYPE(r->l32[0]) != UAPI_IOC_TYPE(r->nat[0]) ||
        UAPI_IOC_NR(r->l32[0]) != UAPI_IOC_NR(r->nat[0]) ||
        UAPI_IOC_SIZE(r->l32[0]) != (r->count ? size : 0)) {
        mismatch(r, "decoded size", size, UAPI_IOC_SIZE(r->l32[0]));
    }
}

/**
 * Check every row on the host's ABI, then lay out every aggregate and
 * check every number on i386. A host whose 64-bit integer type is its
 * word cannot tell a `long` from a 64-bit member, and checks its own ABI
 * alone. Returns 0 when every check passed and 1 otherwise.
 */
int main(void)
{
    int aggs = 0, members = 0, ioctls = 0, i;
    int words = __builtin_types_compatible_p(uint64_t, uintptr_t) ||
                __builtin_types_compatible_p(int64_t, intptr_t) ||
                __builtin_types_compatible_p(uint64_t, size_t);
    unsigned long size, align;

    for (i = 0; i < NROWS; i++) {
        check_native(&rows[i]);
        aggs += rows[i].what == R_AGG;
        members += rows[i].what == R_MEM;
        ioctls += rows[i].what == R_IOCTL;
        if (words) {
            continue;
        }
        if (rows[i].what == R_AGG) {
            layout32(i, 1, &size, &align);
        } else if (rows[i].what == R_IOCTL) {
            check_ioctl32(&rows[i]);
        }
    }
    if (!failures) {
        printf("drm-abi-hosttest: result: pass: %d aggregates, %d members and %d ioctl numbers "
               "match Linux 6.12 on %s\n",
               aggs, members, ioctls,
               words ? "this host's ABI; i386 not checked" : "this host's ABI and i386");
    }
    return failures != 0;
}
